(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const $ = id => document.getElementById(id);
  const ui = { score: $('score'), speed: $('speed'), best: $('bestScore'), modal: $('modalScreen'), title: $('modalTitle'), text: $('modalText'), play: $('playButton'), playLabel: $('playLabel'), stamp: $('crashStamp'), toast: $('laneToast') };
  const colors = { road:'#555b55', edge:'#d9d3b6', white:'#f5e9c2', green:'#28764a', deep:'#155437', red:'#e3333a', gold:'#edbd4f' };
  let W=0,H=0,dpr=1, roadX=0,roadW=0,laneW=0, last=0, state='ready', score=0, elapsed=0, world=0, spawnIn=.8, best=Number(localStorage.getItem('sylhetSprintBest')||0), traffic=[], particles=[], player={lane:1,x:0,y:0,tilt:0,blink:0};
  let toastTimer=0, touchActive=false;
  ui.best.textContent=String(best).padStart(4,'0');

  function resize(){
    const r=canvas.getBoundingClientRect(); dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.round(r.width*dpr); canvas.height=Math.round(r.height*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0); W=r.width; H=r.height;
    roadW=Math.min(W*.78,470); roadW=Math.max(235,roadW); roadX=(W-roadW)/2; laneW=roadW/4;
    player.y=H*.75; player.x=laneCenter(player.lane);
  }
  function laneCenter(lane){return roadX+laneW*(lane+.5)}
  function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
  function drawBackground(dt){
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#76b96b');g.addColorStop(.52,'#508f52');g.addColorStop(1,'#377b49');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    const scroll=world%170;
    for(let i=-1;i<Math.ceil(H/170)+2;i++){
      let y=i*170+scroll-170;
      // tea garden terraces on both verges
      for(let side of [-1,1]){
        const x=side<0?0:roadX+roadW+16, width=side<0?roadX-14:W-roadX-roadW-16;
        if(width<20)continue;
        ctx.fillStyle=(i%2===0)?'#66a858':'#5b9c50';ctx.fillRect(x,y,width,170);
        ctx.save();ctx.beginPath();ctx.rect(x,y,width,170);ctx.clip();
        ctx.strokeStyle='#9ac56d55';ctx.lineWidth=2;
        for(let row=0;row<8;row++){let yy=y+row*23+10;ctx.beginPath();ctx.moveTo(x-20,yy);ctx.quadraticCurveTo(x+width*.5,yy-12,x+width+20,yy+1);ctx.stroke();}
        // leafy shade trees and village details
        for(let n=0;n<3;n++){
          let tx=side<0?x+14+((n*73+i*19)%(Math.max(28,width-26))):x+width-14-((n*73+i*19)%(Math.max(28,width-26)));
          let ty=y+25+n*54;
          drawTree(tx,ty, .72+((n+i+8)%3)*.1);
        }
        if(i%3===0 && width>105){
          const hx=side<0?x+width*.52:x+width*.48, hy=y+105;
          drawHut(hx,hy,side);
        }
        if(i%5===1 && width>115){
          const px=side<0?x+width*.68:x+width*.30;
          ctx.fillStyle='#87c9b0';ctx.beginPath();ctx.ellipse(px,y+48,25,11,.05,0,Math.PI*2);ctx.fill();
          ctx.strokeStyle='#c2dfb6';ctx.lineWidth=2;ctx.stroke();
        }
        ctx.restore();
      }
    }
    // roadside shoulders and road bed
    ctx.fillStyle='#b9a875';ctx.fillRect(roadX-14,0,roadW+28,H);
    ctx.fillStyle='#d9d0ad';ctx.fillRect(roadX-6,0,roadW+12,H);
    ctx.fillStyle=colors.road;ctx.fillRect(roadX,0,roadW,H);
    // slightly mottled asphalt
    for(let i=0;i<14;i++){let yy=((i*103+world*.34)%(H+30))-15;let xx=roadX+12+((i*71)%Math.max(20,roadW-24));ctx.fillStyle='#ffffff08';ctx.fillRect(xx,yy,2,9);}
    // outer shoulder lines
    ctx.fillStyle='#ece2bf';ctx.fillRect(roadX+3,0,3,H);ctx.fillRect(roadX+roadW-6,0,3,H);
    // broken lane markings
    const dash=42,gap=34,offset=world%(dash+gap);
    ctx.fillStyle='#e6dfc4';
    for(let l=1;l<4;l++)for(let y=-dash+offset;y<H;y+=dash+gap)ctx.fillRect(roadX+laneW*l-1.2,y,2.4,dash);
    // little red-green roadside flag pennants on posts
    for(let i=-1;i<Math.ceil(H/245)+2;i++){
      const y=i*245+(world*.72%245)-175;
      drawRoadFlag(roadX-11,y,true);drawRoadFlag(roadX+roadW+11,y,false);
    }
    // distant hills peeking above the top landscape
    ctx.fillStyle='#3f8352';ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(W*.24,-10,W*.43,18);ctx.quadraticCurveTo(W*.68,-10,W,10);ctx.lineTo(W,0);ctx.fill();
  }
  function drawTree(x,y,s=1){
    ctx.fillStyle='#234d36';ctx.beginPath();ctx.ellipse(x+2*s,y+6*s,13*s,7*s,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#755b37';ctx.fillRect(x-2*s,y-1*s,4*s,12*s);
    ctx.fillStyle='#276a41';ctx.beginPath();ctx.arc(x,y-4*s,12*s,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#4b9251';ctx.beginPath();ctx.arc(x-4*s,y-7*s,7*s,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#78ad57';ctx.beginPath();ctx.arc(x+4*s,y-10*s,4*s,0,Math.PI*2);ctx.fill();
  }
  function drawHut(x,y,side){
    ctx.fillStyle='#214d36';ctx.fillRect(x-14,y+3,30,18);
    ctx.fillStyle='#cfb37a';ctx.fillRect(x-12,y+4,26,15);
    ctx.fillStyle='#9c633c';ctx.beginPath();ctx.moveTo(x-18,y+6);ctx.lineTo(x,y-8);ctx.lineTo(x+19,y+6);ctx.closePath();ctx.fill();
    ctx.fillStyle='#e1c47f';ctx.fillRect(x-5,y+10,7,9);
    if(side<0){ctx.fillStyle='#81bd67';ctx.fillRect(x+14,y+10,3,3);}
  }
  function drawRoadFlag(x,y,left){
    ctx.fillStyle='#e5d7af';ctx.fillRect(x-1,y,2,24);
    ctx.fillStyle='#086f42';ctx.fillRect(x-7,y+2,14,9);
    ctx.fillStyle='#e23139';ctx.beginPath();ctx.arc(x,y+6.5,2.5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#725b36';ctx.fillRect(x-5,y+24,10,2);
  }

const vehicleTypes=[
  {type:'CNG',color:'#16a66a',accent:'#f2c84b',w:.72,h:.88},
  {type:'RICKSHAW',color:'#dc4937',accent:'#f3c64d',w:.74,h:.78},
  {type:'TOMTOM',color:'#f0b838',accent:'#278e62',w:.70,h:.79},
  {type:'BUS',color:'#317bb0',accent:'#f4d15b',w:.88,h:1.28}
];
function vehicleSize(v){let mul=v.type==='BUS'?1.26:1;return {w:Math.min(laneW*v.w,48),h:Math.min(laneW*.74,38)*v.h*mul};}
function drawTraffic(v){
  const {w,h}=vehicleSize(v),x=v.x,y=v.y;
  ctx.save();ctx.translate(x,y);
  // wheel shadows, rubber and soft ground shadow
  ctx.fillStyle='#101711';rr(ctx,-w*.48,-h*.35,w*.96,h*.75,w*.13);ctx.fill();
  ctx.fillStyle='#1c2420';
  for(let s of [-1,1]){rr(ctx,s*(w*.42)-w*.055,-h*.28,w*.12,h*.24,3);ctx.fill();rr(ctx,s*(w*.42)-w*.055,h*.04,w*.12,h*.24,3);ctx.fill();}
  // colorful top-down body
  ctx.fillStyle=v.color;rr(ctx,-w*.39,-h*.48,w*.78,h*.94,w*.17);ctx.fill();
  ctx.fillStyle=v.accent;rr(ctx,-w*.33,-h*.39,w*.66,h*.20,w*.09);ctx.fill();
  // passenger/cabin silhouette
  if(v.type==='CNG'){
    ctx.fillStyle='#d3e2d0';rr(ctx,-w*.28,-h*.10,w*.56,h*.47,w*.13);ctx.fill();
    ctx.fillStyle='#416456';rr(ctx,-w*.22,-h*.04,w*.44,h*.27,w*.08);ctx.fill();
    ctx.fillStyle='#f6d86e';ctx.fillRect(-w*.035,-h*.36,w*.07,h*.25);
    ctx.strokeStyle='#e7e5cd';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-w*.30,h*.01);ctx.lineTo(w*.30,h*.01);ctx.stroke();
  }else if(v.type==='RICKSHAW'){
    ctx.fillStyle='#f5cb54';ctx.beginPath();ctx.moveTo(-w*.36,-h*.07);ctx.quadraticCurveTo(-w*.35,-h*.35,0,-h*.30);ctx.quadraticCurveTo(w*.35,-h*.35,w*.36,-h*.07);ctx.lineTo(w*.28,h*.10);ctx.lineTo(-w*.28,h*.10);ctx.closePath();ctx.fill();
    ctx.fillStyle='#398658';rr(ctx,-w*.25,-h*.04,w*.5,h*.26,w*.07);ctx.fill();
    ctx.strokeStyle='#f9e3a5';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-w*.38,-h*.08);ctx.lineTo(w*.38,-h*.08);ctx.stroke();
    ctx.fillStyle='#f4ddac';ctx.beginPath();ctx.arc(0,h*.32,w*.18,0,Math.PI*2);ctx.fill();
  }else if(v.type==='TOMTOM'){
    ctx.fillStyle='#263a31';rr(ctx,-w*.28,-h*.12,w*.56,h*.44,w*.09);ctx.fill();
    ctx.fillStyle='#9dc4a4';rr(ctx,-w*.21,-h*.08,w*.42,h*.15,w*.05);ctx.fill();
    ctx.fillStyle='#f5f0d7';ctx.fillRect(-w*.30,h*.22,w*.6,h*.045);
  }else{
    ctx.fillStyle='#e5e9d8';rr(ctx,-w*.31,-h*.31,w*.62,h*.48,w*.11);ctx.fill();
    ctx.fillStyle='#3d5e60';rr(ctx,-w*.25,-h*.25,w*.5,h*.18,w*.06);ctx.fill();
    ctx.fillStyle='#98c0b5';rr(ctx,-w*.23,-h*.015,w*.46,h*.13,w*.05);ctx.fill();
    ctx.fillStyle='#eddfb6';rr(ctx,-w*.28,h*.23,w*.56,h*.10,w*.04);ctx.fill();
    ctx.fillStyle='#f6e5ad';ctx.fillRect(-w*.32,h*.39,w*.16,h*.04);ctx.fillRect(w*.16,h*.39,w*.16,h*.04);
  }
  // front-facing lamps (oncoming traffic)
  ctx.fillStyle='#fff0bb';rr(ctx,-w*.31,h*.36,w*.17,h*.10,w*.04);ctx.fill();rr(ctx,w*.14,h*.36,w*.17,h*.10,w*.04);ctx.fill();
  ctx.restore();
  // vehicle tag for instantly readable traffic
  if(h>44){ctx.save();ctx.font='800 6px DM Sans';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText(v.type==='RICKSHAW'?'RICKSHAW':v.type,x,y-h*.52);ctx.restore();}
}
function drawBike(x,y,tilt=0,blink=0){
  const w=Math.min(laneW*.60,34),h=w*1.72;
  ctx.save();ctx.translate(x,y);ctx.rotate(tilt);
  // wheels and frame
  ctx.fillStyle='#111a16';rr(ctx,-w*.19,-h*.49,w*.38,h*.25,w*.14);ctx.fill();
  rr(ctx,-w*.19,h*.25,w*.38,h*.25,w*.14);ctx.fill();
  ctx.strokeStyle='#d5bc72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-h*.23);ctx.lineTo(0,h*.23);ctx.stroke();
  // red tank / body
  ctx.fillStyle='#cf302f';rr(ctx,-w*.29,-h*.20,w*.58,h*.50,w*.20);ctx.fill();
  ctx.fillStyle='#168455';rr(ctx,-w*.21,-h*.12,w*.42,h*.30,w*.15);ctx.fill();
  ctx.fillStyle='#f4c351';rr(ctx,-w*.11,-h*.06,w*.22,h*.19,w*.08);ctx.fill();
  // handlebars
  ctx.strokeStyle='#d6d5bd';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w*.32,-h*.25);ctx.lineTo(w*.32,-h*.25);ctx.moveTo(-w*.27,-h*.30);ctx.lineTo(-w*.27,-h*.22);ctx.moveTo(w*.27,-h*.30);ctx.lineTo(w*.27,-h*.22);ctx.stroke();
  // rider helmet & jacket
  ctx.fillStyle='#23382f';rr(ctx,-w*.32,h*.04,w*.64,h*.28,w*.20);ctx.fill();
  ctx.fillStyle='#e1b988';ctx.beginPath();ctx.arc(0,h*.17,w*.19,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#f4eee0';ctx.beginPath();ctx.arc(0,h*.15,w*.16,Math.PI,0);ctx.fill();
  ctx.fillStyle='#303c38';rr(ctx,-w*.15,h*.14,w*.30,h*.09,w*.07);ctx.fill();
  // headlamp
  ctx.fillStyle='#fff4bc';ctx.beginPath();ctx.ellipse(0,-h*.36,w*.13,h*.055,0,0,Math.PI*2);ctx.fill();
  // small Bangladesh flag on bike tail
  ctx.strokeStyle='#eee3c5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.30,h*.31);ctx.lineTo(w*.30,h*.12);ctx.stroke();
  ctx.fillStyle='#087942';ctx.fillRect(w*.30,h*.12,w*.25,h*.13);ctx.fillStyle='#e32d39';ctx.beginPath();ctx.arc(w*.40,h*.185,w*.045,0,Math.PI*2);ctx.fill();
  if(blink>0&&Math.floor(blink*12)%2===0){ctx.strokeStyle='#fff2a1';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,w*.53,h*.55,0,0,Math.PI*2);ctx.stroke();}
  ctx.restore();
  return {w,h};
}

function startGame(){
  score=0;elapsed=0;world=0;spawnIn=.55;traffic=[];particles=[];player.lane=1;player.x=laneCenter(1);player.tilt=0;player.blink=0;state='playing';
  ui.modal.classList.add('hidden');ui.stamp.classList.remove('visible');ui.score.textContent='0000';ui.speed.textContent='48';
}
function endGame(){
  if(state!=='playing')return;state='over';
  const current=Math.floor(score);
  if(current>best){best=current;localStorage.setItem('sylhetSprintBest',String(best));ui.best.textContent=String(best).padStart(4,'0');}
  ui.title.innerHTML='Ride<br><em>Over</em>';
  ui.text.innerHTML=`You covered <strong>${String(current).padStart(4,'0')} meters</strong> through Sylhet.<br>Ready for one more ride?`;
  ui.playLabel.textContent='RIDE AGAIN';ui.modal.classList.remove('hidden');ui.stamp.classList.add('visible');
  for(let i=0;i<17;i++){let a=Math.random()*Math.PI*2,s=50+Math.random()*180;particles.push({x:player.x,y:player.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.55+Math.random()*.55,color:['#edbd4f','#e53936','#f6ebc6'][i%3]});}
}
function steer(direction){
  if(state!=='playing')return;
  const next=Math.max(0,Math.min(3,player.lane+direction));if(next===player.lane)return;
  player.lane=next;player.tilt=direction*.20;player.blink=.32;
  ui.toast.textContent=direction<0?'PASSING LEFT':'PASSING RIGHT';ui.toast.classList.add('show');toastTimer=.75;
}
function spawnTraffic(){
  // Keep gaps legible while gradually filling the road as speed rises.
  let lane=Math.floor(Math.random()*4);
  for(let tries=0;tries<6;tries++){
    lane=Math.floor(Math.random()*4);
    if(!traffic.some(v=>v.lane===lane&&v.y<145))break;
  }
  const t=vehicleTypes[Math.floor(Math.random()*vehicleTypes.length)];
  traffic.push({type:t.type,color:t.color,accent:t.accent,w:t.w,h:t.h,lane,x:laneCenter(lane),y:-70,seed:Math.random()*8});
}
function update(dt){
  if(state==='playing'){
    elapsed+=dt;const flow=168+Math.min(180,elapsed*3.0);world+=flow*dt;score+=dt*(10+elapsed*.34);
    ui.score.textContent=String(Math.floor(score)).padStart(4,'0');ui.speed.textContent=String(Math.min(168,48+Math.floor(elapsed*1.15)));
    const target=laneCenter(player.lane);player.x+=(target-player.x)*Math.min(1,dt*14);player.tilt*=Math.pow(.08,dt);player.blink=Math.max(0,player.blink-dt);
    spawnIn-=dt;if(spawnIn<=0){spawnTraffic();spawnIn=Math.max(.56,1.08-elapsed*.007)+Math.random()*.25;}
    for(const v of traffic){v.y+=(flow*(v.type==='BUS'?.93:1.12))*dt;v.x=laneCenter(v.lane)+Math.sin(elapsed*.9+v.seed)*1.3;}
    const bike=drawBikeMetrics();
    for(const v of traffic){const size=vehicleSize(v);if(Math.abs(v.x-player.x)<(bike.w+size.w)*.37&&Math.abs(v.y-player.y)<(bike.h+size.h)*.39){endGame();break;}}
    traffic=traffic.filter(v=>v.y<H+100);
  }else if(state==='ready')world+=27*dt;
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.15,dt);p.vy*=Math.pow(.15,dt);p.life-=dt;}
  particles=particles.filter(p=>p.life>0);
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
}
function drawBikeMetrics(){const w=Math.min(laneW*.60,34);return {w,h:w*1.72};}

  function render(){
    drawBackground(0);
    // soft roadside haze and warm afternoon light
    const glow=ctx.createRadialGradient(W*.5,H*.14,8,W*.5,H*.14,H*.78);glow.addColorStop(0,'#fff0a00d');glow.addColorStop(1,'#06281e26');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
    for(const v of traffic)drawTraffic(v);
    const idleBob=state==='ready'?Math.sin(performance.now()*.003)*2:0;
    drawBike(player.x||laneCenter(player.lane),player.y+idleBob,player.tilt,player.blink);
    for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2+Math.min(3,p.life*3),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    // subtle edge vignette keeps the road scene legible under the HUD
    const vignette=ctx.createLinearGradient(0,0,W,0);vignette.addColorStop(0,'#082b1c29');vignette.addColorStop(.16,'transparent');vignette.addColorStop(.84,'transparent');vignette.addColorStop(1,'#082b1c29');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);
  }
  function frame(now){
    const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame);
  }
  function bindSteer(id,direction){
    const button=$(id);
    button.addEventListener('pointerdown',e=>{e.preventDefault();button.classList.add('pressed');steer(direction);});
    const release=()=>button.classList.remove('pressed');button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('pointerleave',release);
  }
  bindSteer('leftButton',-1);bindSteer('rightButton',1);
  ui.play.addEventListener('click',startGame);
  window.addEventListener('keydown',e=>{
    if(['ArrowLeft','ArrowRight',' ','a','A','d','D'].includes(e.key))e.preventDefault();
    if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')steer(-1);
    else if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')steer(1);
    else if((e.key===' '||e.key==='Enter')&&state!=='playing')startGame();
  },{passive:false});
  window.addEventListener('resize',resize,{passive:true});
  document.addEventListener('visibilitychange',()=>{last=performance.now();});
  resize();player.x=laneCenter(player.lane);player.y=H*.75;requestAnimationFrame(frame);
})();

