(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const $ = id => document.getElementById(id);
  const ui = { score: $('score'), speed: $('speed'), best: $('bestScore'), modal: $('modalScreen'), title: $('modalTitle'), text: $('modalText'), play: $('playButton'), playLabel: $('playLabel'), stamp: $('crashStamp'), toast: $('laneToast') };
  const colors = { road:'#555b55', edge:'#d9d3b6', white:'#f5e9c2', green:'#28764a', deep:'#155437', red:'#e3333a', gold:'#edbd4f' };
