const vehicleTypes=[{type:'CNG',color:'#16a66a',accent:'#f2c84b',w:.72,h:.88},{type:'RICKSHAW',color:'#dc4937',accent:'#f3c64d',w:.74,h:.78},{type:'TOMTOM',color:'#f0b838',accent:'#278e62',w:.70,h:.79},{type:'BUS',color:'#317bb0',accent:'#f4d15b',w:.88,h:1.28}];
function vehicleSize(v){let mul=v.type==='BUS'?1.26:1;return {w:Math.min(laneW*v.w,48),h:Math.min(laneW*.74,38)*v.h*mul};}
function drawTraffic(v){
  const {w,h}=vehicleSize(v),x=v.x,y=v.y;ctx.save();ctx.translate(x,y);
  ctx.fillStyle='#101711';rr(ctx,-w*.48,-h*.35,w*.96,h*.75,w*.13);ctx.fill();ctx.fillStyle='#1c2420';
  for(let s of [-1,1]){rr(ctx,s*(w*.42)-w*.055,-h*.28,w*.12,h*.24,3);ctx.fill();rr(ctx,s*(w*.42)-w*.055,h*.04,w*.12,h*.24,3);ctx.fill();}
  ctx.fillStyle=v.color;rr(ctx,-w*.39,-h*.48,w*.78,h*.94,w*.17);ctx.fill();ctx.fillStyle=v.accent;rr(ctx,-w*.33,-h*.39,w*.66,h*.20,w*.09);ctx.fill();
  if(v.type==='CNG'){ctx.fillStyle='#d3e2d0';rr(ctx,-w*.28,-h*.10,w*.56,h*.47,w*.13);ctx.fill();ctx.fillStyle='#416456';rr(ctx,-w*.22,-h*.04,w*.44,h*.27,w*.08);ctx.fill();ctx.fillStyle='#f6d86e';ctx.fillRect(-w*.035,-h*.36,w*.07,h*.25);ctx.strokeStyle='#e7e5cd';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-w*.30,h*.01);ctx.lineTo(w*.30,h*.01);ctx.stroke();}
  else if(v.type==='RICKSHAW'){ctx.fillStyle='#f5cb54';ctx.beginPath();ctx.moveTo(-w*.36,-h*.07);ctx.quadraticCurveTo(-w*.35,-h*.35,0,-h*.30);ctx.quadraticCurveTo(w*.35,-h*.35,w*.36,-h*.07);ctx.lineTo(w*.28,h*.10);ctx.lineTo(-w*.28,h*.10);ctx.closePath();ctx.fill();ctx.fillStyle='#398658';rr(ctx,-w*.25,-h*.04,w*.5,h*.26,w*.07);ctx.fill();ctx.strokeStyle='#f9e3a5';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-w*.38,-h*.08);ctx.lineTo(w*.38,-h*.08);ctx.stroke();ctx.fillStyle='#f4ddac';ctx.beginPath();ctx.arc(0,h*.32,w*.18,0,Math.PI*2);ctx.fill();}
  else if(v.type==='TOMTOM'){ctx.fillStyle='#263a31';rr(ctx,-w*.28,-h*.12,w*.56,h*.44,w*.09);ctx.fill();ctx.fillStyle='#9dc4a4';rr(ctx,-w*.21,-h*.08,w*.42,h*.15,w*.05);ctx.fill();ctx.fillStyle='#f5f0d7';ctx.fillRect(-w*.30,h*.22,w*.6,h*.045);}
  else{ctx.fillStyle='#e5e9d8';rr(ctx,-w*.31,-h*.31,w*.62,h*.48,w*.11);ctx.fill();ctx.fillStyle='#3d5e60';rr(ctx,-w*.25,-h*.25,w*.5,h*.18,w*.06);ctx.fill();ctx.fillStyle='#98c0b5';rr(ctx,-w*.23,-h*.015,w*.46,h*.13,w*.05);ctx.fill();ctx.fillStyle='#eddfb6';rr(ctx,-w*.28,h*.23,w*.56,h*.10,w*.04);ctx.fill();ctx.fillStyle='#f6e5ad';ctx.fillRect(-w*.32,h*.39,w*.16,h*.04);ctx.fillRect(w*.16,h*.39,w*.16,h*.04);}
  ctx.fillStyle='#fff0bb';rr(ctx,-w*.31,h*.36,w*.17,h*.10,w*.04);ctx.fill();rr(ctx,w*.14,h*.36,w*.17,h*.10,w*.04);ctx.fill();ctx.restore();
  if(h>44){ctx.save();ctx.font='800 6px DM Sans';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText(v.type,x,y-h*.52);ctx.restore();}
}
function drawBike(x,y,tilt=0,blink=0){const w=Math.min(laneW*.60,34),h=w*1.72;ctx.save();ctx.translate(x,y);ctx.rotate(tilt);ctx.fillStyle='#111a16';rr(ctx,-w*.19,-h*.49,w*.38,h*.25,w*.14);ctx.fill();rr(ctx,-w*.19,h*.25,w*.38,h*.25,w*.14);ctx.fill();ctx.strokeStyle='#d5bc72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-h*.23);ctx.lineTo(0,h*.23);ctx.stroke();ctx.fillStyle='#cf302f';rr(ctx,-w*.29,-h*.20,w*.58,h*.50,w*.20);ctx.fill();ctx.fillStyle='#168455';rr(ctx,-w*.21,-h*.12,w*.42,h*.30,w*.15);ctx.fill();ctx.fillStyle='#f4c351';rr(ctx,-w*.11,-h*.06,w*.22,h*.19,w*.08);ctx.fill();ctx.strokeStyle='#d6d5bd';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w*.32,-h*.25);ctx.lineTo(w*.32,-h*.25);ctx.moveTo(-w*.27,-h*.30);ctx.lineTo(-w*.27,-h*.22);ctx.moveTo(w*.27,-h*.30);ctx.lineTo(w*.27,-h*.22);ctx.stroke();ctx.fillStyle='#23382f';rr(ctx,-w*.32,h*.04,w*.64,h*.28,w*.20);ctx.fill();ctx.fillStyle='#e1b988';ctx.beginPath();ctx.arc(0,h*.17,w*.19,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f4eee0';ctx.beginPath();ctx.arc(0,h*.15,w*.16,Math.PI,0);ctx.fill();ctx.fillStyle='#303c38';rr(ctx,-w*.15,h*.14,w*.30,h*.09,w*.07);ctx.fill();ctx.fillStyle='#fff4bc';ctx.beginPath();ctx.ellipse(0,-h*.36,w*.13,h*.055,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#eee3c5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.30,h*.31);ctx.lineTo(w*.30,h*.12);ctx.stroke();ctx.fillStyle='#087942';ctx.fillRect(w*.30,h*.12,w*.25,h*.13);ctx.fillStyle='#e32d39';ctx.beginPath();ctx.arc(w*.40,h*.185,w*.045,0,Math.PI*2);ctx.fill();if(blink>0&&Math.floor(blink*12)%2===0){ctx.strokeStyle='#fff2a1';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,w*.53,h*.55,0,0,Math.PI*2);ctx.stroke();}ctx.restore();return {w,h};}
function startGame(){score=0;elapsed=0;world=0;spawnIn=.55;traffic=[];particles=[];player.lane=1;player.x=laneCenter(1);player.tilt=0;player.blink=0;state='playing';ui.modal.classList.add('hidden');ui.stamp.classList.remove('visible');ui.score.textContent='0000';ui.speed.textContent='48';}
function endGame(){if(state!=='playing')return;state='over';const current=Math.floor(score);if(current>best){best=current;localStorage.setItem('sylhetSprintBest',String(best));ui.best.textContent=String(best).padStart(4,'0');}ui.title.innerHTML='Ride<br><em>Over</em>';ui.text.innerHTML=`You covered <strong>${String(current).padStart(4,'0')} meters</strong> through Sylhet.<br>Ready for one more ride?`;ui.playLabel.textContent='RIDE AGAIN';ui.modal.classList.remove('hidden');ui.stamp.classList.add('visible');for(let i=0;i<17;i++){let a=Math.random()*Math.PI*2,s=50+Math.random()*180;particles.push({x:player.x,y:player.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.55+Math.random()*.55,color:['#edbd4f','#e53936','#f6ebc6'][i%3]});}}
function steer(direction){if(state!=='playing')return;const next=Math.max(0,Math.min(3,player.lane+direction));if(next===player.lane)return;player.lane=next;player.tilt=direction*.20;player.blink=.32;ui.toast.textContent=direction<0?'PASSING LEFT':'PASSING RIGHT';ui.toast.classList.add('show');toastTimer=.75;}
function spawnTraffic(){let lane=0;for(let tries=0;tries<6;tries++){lane=Math.floor(Math.random()*4);if(!traffic.some(v=>v.lane===lane&&v.y<145))break;}const t=vehicleTypes[Math.floor(Math.random()*vehicleTypes.length)];traffic.push({type:t.type,color:t.color,accent:t.accent,w:t.w,h:t.h,lane,x:laneCenter(lane),y:-70,seed:Math.random()*8});}
/*NEXT*/

